async fn ring(scope: &EpisodeScope, seq: u64) -> anyhow::Result<()> {
    let args = serde_json::json!({
        "owner_key": crate::wake_doorbell::owner_key(scope),
        "seq": seq,
    });
    op_plugins::state_plugins::emqx::dispatch_emqx_method("publish_wake", &args).await?;
    Ok(())
}

